// Copies the typed ABIs generated by the backend (from the audited contract build) into the web app,
// so both always use identical ABIs. Run after `npm run gen:abis` in backend/.
import { copyFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const from = fileURLToPath(new URL("../../backend/packages/contracts/src/abis.ts", import.meta.url));
const to = fileURLToPath(new URL("../src/lib/abis.ts", import.meta.url));
copyFileSync(from, to);
console.log(`Copied ABIs to ${to}`);
